import { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, AlignmentType, WidthType, BorderStyle, VerticalAlign, HeightRule } from "docx";
import FileSaver from "file-saver";
import { FormData } from "../types";

export async function exportToDocx(formData: FormData) {
  const doc = new Document({
    styles: {
      default: {
        document: {
          run: {
            size: 26, // 13pt
            font: "Times New Roman",
            color: "000000", // Đảm bảo toàn bộ chữ màu đen
          },
        },
      },
    },
    sections: [
      {
        properties: {
          page: {
            margin: {
              top: 720,
              right: 720,
              bottom: 720,
              left: 720,
            },
          },
        },
        children: [
          // Header Section with Logo Table (Đã loại bỏ màu nền và màu chữ đỏ của logo)
          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
              top: { style: BorderStyle.SINGLE, size: 4 },
              bottom: { style: BorderStyle.SINGLE, size: 4 },
              left: { style: BorderStyle.SINGLE, size: 4 },
              right: { style: BorderStyle.SINGLE, size: 4 },
              insideHorizontal: { style: BorderStyle.SINGLE, size: 4 },
              insideVertical: { style: BorderStyle.SINGLE, size: 4 },
            },
            rows: [
              new TableRow({
                height: { value: 1000, rule: HeightRule.ATLEAST },
                children: [
                  // Logo Cell (Chuyển sang đen trắng)
                  new TableCell({
                    width: { size: 25, type: WidthType.PERCENTAGE },
                    verticalAlign: VerticalAlign.CENTER,
                    children: [
                      new Table({
                        width: { size: 95, type: WidthType.PERCENTAGE },
                        alignment: AlignmentType.CENTER,
                        borders: {
                          top: { style: BorderStyle.SINGLE, size: 1 },
                          bottom: { style: BorderStyle.SINGLE, size: 1 },
                          left: { style: BorderStyle.SINGLE, size: 1 },
                          right: { style: BorderStyle.SINGLE, size: 1 },
                          insideHorizontal: { style: BorderStyle.NONE },
                          insideVertical: { style: BorderStyle.SINGLE, size: 1 },
                        },
                        rows: [
                          new TableRow({
                            children: ["B", "T", "I"].map(letter => 
                              new TableCell({
                                verticalAlign: VerticalAlign.CENTER,
                                children: [
                                  new Paragraph({
                                    alignment: AlignmentType.CENTER,
                                    children: [
                                      new TextRun({ 
                                        text: letter, 
                                        bold: true, 
                                        size: 48,
                                        color: "000000"
                                      })
                                    ]
                                  })
                                ],
                              })
                            )
                          })
                        ]
                      })
                    ],
                  }),
                  // Title Cell
                  new TableCell({
                    width: { size: 55, type: WidthType.PERCENTAGE },
                    verticalAlign: VerticalAlign.CENTER,
                    children: [
                      new Paragraph({
                        alignment: AlignmentType.CENTER,
                        children: [
                          new TextRun({ text: "TỜ TRÌNH", bold: true, size: 32 }),
                        ],
                      }),
                      new Paragraph({
                        alignment: AlignmentType.CENTER,
                        children: [
                          new TextRun({ text: `"${formData.title}"`, bold: true, size: 26 }),
                        ],
                      }),
                    ],
                  }),
                  // Document Number Cell
                  new TableCell({
                    width: { size: 20, type: WidthType.PERCENTAGE },
                    verticalAlign: VerticalAlign.CENTER,
                    children: [
                      new Paragraph({
                        alignment: AlignmentType.CENTER,
                        children: [
                          new TextRun({ text: formData.docNumber || "QTMH-BM02", bold: true, size: 20 }),
                        ],
                      }),
                    ],
                  }),
                ],
              }),
            ],
          }),

          new Paragraph({ spacing: { before: 200 } }),
          new Paragraph({
            alignment: AlignmentType.RIGHT,
            children: [
              new TextRun({ text: `${formData.location || "Tp. Hồ Chí Minh"}, ngày ${formData.date || "..."}`, italics: true }),
            ],
          }),

          new Paragraph({ spacing: { before: 200 } }),
          new Paragraph({
            children: [
              new TextRun({ text: "Kính gửi:", bold: true }),
              ...formData.recipients.map(r => new TextRun({ text: `\n- ${r}`, bold: false }))
            ],
          }),

          new Paragraph({ spacing: { before: 200 } }),
          ...formData.grounds.map(g => new Paragraph({
            children: [new TextRun({ text: `- ${g}` })],
          })),

          new Paragraph({
            spacing: { before: 200, after: 200 },
            children: [
              new TextRun({ text: "Phòng kỹ thuật kính trình Hội đồng thành viên và BGĐ Công ty TNHH MTV Thương Mại Becamex phê duyệt dự trù kinh phí mua vật tư thi công " }),
              new TextRun({ text: formData.title.replace(/^V\/v:\s*/i, ""), bold: true }),
              new TextRun({ text: ", nội dung sau:" }),
            ],
          }),

          new Paragraph({
            children: [new TextRun({ text: "1/ Mua vật tư, thiết bị:", bold: true, underline: {} })],
            spacing: { after: 100 },
          }),

          // Items Table (Đã loại bỏ các định dạng màu đỏ)
          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            rows: [
              new TableRow({
                children: ["Stt", "Vật tư/Thiết bị", "Đvt", "SL", "Đơn giá", "Thành tiền", "Ghi chú"].map(
                  (text) =>
                    new TableCell({
                      children: [new Paragraph({ text, bold: true, alignment: AlignmentType.CENTER })],
                      verticalAlign: VerticalAlign.CENTER,
                    })
                ),
              }),
              ...formData.items.map(
                (item) =>
                  new TableRow({
                    children: [
                      new TableCell({ children: [new Paragraph({ text: item.stt.toString(), alignment: AlignmentType.CENTER })] }),
                      new TableCell({ children: [new Paragraph({ text: item.name })] }),
                      new TableCell({ children: [new Paragraph({ text: item.unit, alignment: AlignmentType.CENTER })] }),
                      new TableCell({ children: [new Paragraph({ text: item.quantity.toLocaleString('vi-VN'), alignment: AlignmentType.CENTER })] }),
                      new TableCell({ children: [new Paragraph({ text: item.unitPrice.toLocaleString('vi-VN'), alignment: AlignmentType.RIGHT })] }),
                      new TableCell({ children: [new Paragraph({ text: item.total.toLocaleString('vi-VN'), alignment: AlignmentType.RIGHT, bold: true })] }),
                      new TableCell({ children: [new Paragraph({ text: item.note, alignment: AlignmentType.CENTER })] }),
                    ],
                  })
              ),
              new TableRow({
                children: [
                  new TableCell({ columnSpan: 5, children: [new Paragraph({ text: "Tổng cộng (đã bao gồm thuế GTGT)", bold: true, alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: formData.totalAmount.toLocaleString('vi-VN'), bold: true, alignment: AlignmentType.RIGHT })] }),
                  new TableCell({ children: [new Paragraph({ text: "" })] }),
                ],
              }),
            ],
          }),

          new Paragraph({ spacing: { before: 400 } }),
          new Paragraph({
            children: [new TextRun({ text: "Xác nhận của bộ phận QLVT (nếu có):", bold: true, underline: {} })],
          }),
          new Paragraph({ text: "(Khối lượng còn trong kho được ghi tại cột ghi chú ở bảng trên)", italics: true }),
          new Paragraph({ text: "..........................................................................................................................................." }),
          new Paragraph({ text: "..........................................................................................................................................." }),

          new Paragraph({ spacing: { before: 400 } }),
          new Paragraph({ text: "Trân trọng!", alignment: AlignmentType.LEFT }),

          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
              top: { style: BorderStyle.NONE },
              bottom: { style: BorderStyle.NONE },
              left: { style: BorderStyle.NONE },
              right: { style: BorderStyle.NONE },
              insideHorizontal: { style: BorderStyle.NONE },
              insideVertical: { style: BorderStyle.NONE },
            },
            rows: [
              new TableRow({
                children: [
                  new TableCell({ children: [new Paragraph({ text: "Phòng Kế toán", bold: true, alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: "Phòng Kỹ thuật", bold: true, alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: "Người lập", bold: true, alignment: AlignmentType.CENTER })] }),
                ],
              }),
              new TableRow({ height: { value: 1000, rule: HeightRule.ATLEAST }, children: [new TableCell({ children: [] }), new TableCell({ children: [] }), new TableCell({ children: [] })] }),
              new TableRow({
                children: [
                  new TableCell({ children: [new Paragraph({ text: "Phòng Kinh doanh", bold: true, alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: "Giám đốc", bold: true, alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: "Duyệt HĐTV", bold: true, alignment: AlignmentType.CENTER })] }),
                ],
              }),
            ],
          }),
        ],
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  const cleanTitle = formData.title.replace(/^V\/v:\s*/i, "").substring(0, 50).replace(/[\s\W]+/g, '_');
  const fileName = `To_Trinh_${cleanTitle}.docx`;

  if (typeof FileSaver.saveAs === 'function') {
    FileSaver.saveAs(blob, fileName);
  } else {
    (FileSaver as any)(blob, fileName);
  }
}

