                  new TableCell({ children: [new Paragraph({ text: "Phòng Kinh doanh", bold: true, alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: "Giám đốc", bold: true, alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: "Duyệt HĐTV", bold: true, alignment: AlignmentType.CENTER })] }),
                ],
              }),
            ],
          }),
        ],
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  const cleanTitle = formData.title.replace(/^V\/v:\s*/i, "").substring(0, 50).replace(/[\s\W]+/g, '_');
  const fileName = `To_Trinh_${cleanTitle}.docx`;

  if (typeof FileSaver.saveAs === 'function') {
    FileSaver.saveAs(blob, fileName);
  } else {
    (FileSaver as any)(blob, fileName);
  }
}

import { GoogleGenAI, Type } from "@google/genai";
import { FormData } from "../types";

export async function extractDataFromPdf(fileBase64: string): Promise<FormData> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Bạn là một chuyên gia trích xuất dữ liệu hành chính từ tài liệu xây dựng Việt Nam.
  Hãy phân tích kỹ file PDF và thực hiện các bước sau:

  1. XÁC ĐỊNH THÔNG TIN CHÍNH:
     - Tìm mục "Nội dung": ví dụ "Đổ bê tông lót đà kiềng căn 56".
     - Tìm mục "Địa điểm": ví dụ "Căn 56 Lô N7 – N8 thuộc dự án Khu nhà ở độc lập biệt thự Sunflower...".
     - Tìm dòng thời gian: ví dụ "ngày 17 tháng 11 năm 2025".

  2. CẤU TRÚC LẠI DỮ LIỆU VÀO FORM:
     - Title (Tiêu đề): Ghép theo mẫu: "V/v: Phê duyệt dự trù kinh phí mua vật tư thi công: [Nội dung] [Địa điểm]".
     - QUY TẮC QUAN TRỌNG ĐỂ TRÁNH LẶP TỪ: 
       + Nếu trong phần [Nội dung] đã có số căn (ví dụ: "căn 56") và phần [Địa điểm] cũng bắt đầu bằng số căn đó (ví dụ: "Căn 56 Lô..."), hãy HỢP NHẤT chúng lại để số căn chỉ xuất hiện 1 lần duy nhất.
       + Ví dụ đúng: "V/v: Phê duyệt dự trù kinh phí mua vật tư thi công: Đổ bê tông lót đà kiềng Căn 56 Lô N7 – N8 thuộc dự án Khu nhà ở độc lập biệt thự Sunflower".
       + Ví dụ sai: "...đà kiềng căn 56 Căn 56 Lô...".
     - LOẠI BỎ THÔNG TIN ĐỊA CHỈ: Không lấy "Phường...", "Quận...", "TP. Hồ Chí Minh", "Tỉnh..." trong tiêu đề.
     - Location (Địa điểm): Mặc định luôn là "Tp. Hồ Chí Minh".
     - Date (Ngày): Lấy phần sau chữ "ngày" bao gồm cả tháng và năm.

  3. TRÍCH XUẤT BẢNG VẬT TƯ:
     - Liệt kê đầy đủ các mặt hàng: Tên vật tư, Đvt, Số lượng, Đơn giá.

  Trả về kết quả dưới dạng JSON. Cố định docNumber là "QTMH-BM02".`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          {
            inlineData: {
              mimeType: 'application/pdf',
              data: fileBase64,
            },
          },
          { text: prompt },
        ],
      },
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          docNumber: { type: Type.STRING },
          title: { type: Type.STRING },
          date: { type: Type.STRING },
          location: { type: Type.STRING },
          recipients: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          grounds: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          items: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                stt: { type: Type.INTEGER },
                name: { type: Type.STRING },
                unit: { type: Type.STRING },
                quantity: { type: Type.NUMBER },
                unitPrice: { type: Type.NUMBER },
                total: { type: Type.NUMBER },
                note: { type: Type.STRING }
              }
            }
          }
        },
        required: ["title", "items"]
      },
    },
  });

  try {
    const textOutput = response.text;
    const rawData = JSON.parse(textOutput);

    return {
      docNumber: 'QTMH-BM02',
      title: rawData.title || 'Tờ trình phê duyệt kinh phí',
      date: rawData.date || '... tháng ... năm 2025',
      location: 'Tp. Hồ Chí Minh',
      recipients: rawData.recipients && rawData.recipients.length > 0 
        ? rawData.recipients 
        : ['CÔNG TY TNHH MTV THƯƠNG MẠI BECAMEX (BTI)'],
      grounds: rawData.grounds && rawData.grounds.length > 0
        ? rawData.grounds
        : [
            'Hợp đồng thi công xây dựng số 1710/2025/HĐXD/ BTI-AN THINH',
            'Hồ sơ thiết kế thi công, dự toán được duyệt'
          ],
      items: (rawData.items || []).map((item: any, index: number) => ({
        id: Math.random().toString(36).substr(2, 9),
        stt: item.stt || index + 1,
        name: item.name || '',
        unit: item.unit || 'm3',
        quantity: item.quantity || 0,
        unitPrice: item.unitPrice || 0,
        total: (item.quantity || 0) * (item.unitPrice || 0),
        note: item.note || ''
      })),
      totalAmount: (rawData.items || []).reduce((sum: number, item: any) => sum + ((item.quantity || 0) * (item.unitPrice || 0)), 0)
    };
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    throw new Error("Không thể trích xuất dữ liệu. Vui lòng kiểm tra lại file PDF.");
  }
}

