import { GoogleGenAI, Type } from "@google/genai";
import { FormData } from "../types";

export async function extractDataFromPdf(fileBase64: string): Promise<FormData> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Bạn là một chuyên gia trích xuất dữ liệu hành chính từ tài liệu xây dựng Việt Nam.
  Hãy phân tích kỹ file PDF và thực hiện các bước sau:

  1. XÁC ĐỊNH THÔNG TIN CHÍNH:
     - Tìm mục "Nội dung": ví dụ "Đổ bê tông lót đà kiềng căn 56".
     - Tìm mục "Địa điểm": ví dụ "Căn 56 Lô N7 – N8 thuộc dự án Khu nhà ở độc lập biệt thự Sunflower...".
     - Tìm dòng thời gian: ví dụ "ngày 17 tháng 11 năm 2025".

  2. CẤU TRÚC LẠI DỮ LIỆU VÀO FORM:
     - Title (Tiêu đề): Ghép theo mẫu: "V/v: Phê duyệt dự trù kinh phí mua vật tư thi công: [Nội dung] [Địa điểm]".
     - QUY TẮC QUAN TRỌNG ĐỂ TRÁNH LẶP TỪ: 
       + Nếu trong phần [Nội dung] đã có số căn (ví dụ: "căn 56") và phần [Địa điểm] cũng bắt đầu bằng số căn đó (ví dụ: "Căn 56 Lô..."), hãy HỢP NHẤT chúng lại để số căn chỉ xuất hiện 1 lần duy nhất.
       + Ví dụ đúng: "V/v: Phê duyệt dự trù kinh phí mua vật tư thi công: Đổ bê tông lót đà kiềng Căn 56 Lô N7 – N8 thuộc dự án Khu nhà ở độc lập biệt thự Sunflower".
       + Ví dụ sai: "...đà kiềng căn 56 Căn 56 Lô...".
     - LOẠI BỎ THÔNG TIN ĐỊA CHỈ: Không lấy "Phường...", "Quận...", "TP. Hồ Chí Minh", "Tỉnh..." trong tiêu đề.
     - Location (Địa điểm): Mặc định luôn là "Tp. Hồ Chí Minh".
     - Date (Ngày): Lấy phần sau chữ "ngày" bao gồm cả tháng và năm.

  3. TRÍCH XUẤT BẢNG VẬT TƯ:
     - Liệt kê đầy đủ các mặt hàng: Tên vật tư, Đvt, Số lượng, Đơn giá.
     - LƯU Ý ĐẶC BIỆT VỀ ĐƠN VỊ TÍNH (Đvt):
       + Đối với các loại "Bơm bê tông", "Bơm ca bê tông", đơn vị tính thường là "ca". Hãy kiểm tra kỹ và trích xuất đúng là "ca" nếu tài liệu ghi vậy, không tự ý đổi sang "m3".

  Trả về kết quả dưới dạng JSON. Cố định docNumber là "QTMH-BM02".`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        parts: [
          {
            inlineData: {
              mimeType: 'application/pdf',
              data: fileBase64,
            },
          },
          { text: prompt },
        ],
      },
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          docNumber: { type: Type.STRING },
          title: { type: Type.STRING },
          date: { type: Type.STRING },
          location: { type: Type.STRING },
          items: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                stt: { type: Type.INTEGER },
                name: { type: Type.STRING },
                unit: { type: Type.STRING },
                quantity: { type: Type.NUMBER },
                unitPrice: { type: Type.NUMBER },
                total: { type: Type.NUMBER },
                note: { type: Type.STRING }
              }
            }
          }
        },
        required: ["title", "items"]
      },
    },
  });

  try {
    const textOutput = response.text;
    const rawData = JSON.parse(textOutput);

    return {
      docNumber: 'QTMH-BM02',
      title: rawData.title || 'Tờ trình phê duyệt kinh phí',
      date: rawData.date || '... tháng ... năm 2025',
      location: 'Tp. Hồ Chí Minh',
      recipients: [
        'Hội Đồng Thành Viên',
        'BGĐ Công ty TNHH MTV Thương Mại Becamex'
      ],
      grounds: [
        'Phiếu đề nghị về việc cung cấp vật tư của Công ty An Thịnh',
        'Báo giá của Công ty CP KD và PT Bình Dương - Xí Nghiệp Bê Tông Trộn Sẵn Mỹ Phước'
      ],
      items: (rawData.items || []).map((item: any, index: number) => ({
        id: Math.random().toString(36).substr(2, 9),
        stt: item.stt || index + 1,
        name: item.name || '',
        unit: item.unit || 'm3',
        quantity: item.quantity || 0,
        unitPrice: item.unitPrice || 0,
        total: (item.quantity || 0) * (item.unitPrice || 0),
        note: item.note || ''
      })),
      totalAmount: (rawData.items || []).reduce((sum: number, item: any) => sum + ((item.quantity || 0) * (item.unitPrice || 0)), 0)
    };
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    throw new Error("Không thể trích xuất dữ liệu. Vui lòng kiểm tra lại file PDF.");
  }
}

import React, { useState } from 'react';
import { Upload, FileText, Download, Loader2, Plus, Trash2, AlertCircle } from 'lucide-react';
import { extractDataFromPdf } from './services/geminiService';
import { exportToDocx } from './services/docxExport';
import { FormData, LineItem, UNIT_OPTIONS } from './types';

const FIXED_RECIPIENTS = [
  'Hội Đồng Thành Viên',
  'BGĐ Công ty TNHH MTV Thương Mại Becamex'
];

const INITIAL_FORM: FormData = {
  docNumber: 'QTMH-BM02',
  title: 'Phê duyệt dự trù kinh phí mua vật tư thi công...',
  date: '... tháng ... năm 2025',
  location: 'Tp. Hồ Chí Minh',
  recipients: FIXED_RECIPIENTS,
  grounds: [
    'Phiếu đề nghị về việc cung cấp vật tư của Công ty An Thịnh',
    'Báo giá của Công ty CP KD và PT Bình Dương - Xí Nghiệp Bê Tông Trộn Sẵn Mỹ Phước'
  ],
  items: [],
  totalAmount: 0
};

export default function App() {
  const [formData, setFormData] = useState<FormData>(INITIAL_FORM);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      setError("Vui lòng tải lên file định dạng PDF.");
      return;
    }

    setIsProcessing(true);
    setError(null);

    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const extracted = await extractDataFromPdf(base64);
        setFormData({
          ...extracted,
          docNumber: 'QTMH-BM02',
          location: 'Tp. Hồ Chí Minh',
          recipients: FIXED_RECIPIENTS // Luôn giữ danh sách người nhận cố định
        });
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    } catch (err: any) {
      setError(err.message || "Đã có lỗi xảy ra khi xử lý file.");
      setIsProcessing(false);
    }
  };

  const updateItem = (id: string, field: keyof LineItem, value: any) => {
    setFormData(prev => {
      const newItems = prev.items.map(item => {
        if (item.id === id) {
          const updated = { ...item, [field]: value };
          if (field === 'quantity' || field === 'unitPrice') {
            updated.total = (updated.quantity || 0) * (updated.unitPrice || 0);
          }
          return updated;
        }
        return item;
      });
      const newTotal = newItems.reduce((sum, item) => sum + (item.total || 0), 0);
      return { ...prev, items: newItems, totalAmount: newTotal };
    });
  };

  const addItem = () => {
    const newItem: LineItem = {
      id: Math.random().toString(36).substr(2, 9),
      stt: formData.items.length + 1,
      name: '',
      unit: 'm3',
      quantity: 0,
      unitPrice: 0,
      total: 0,
      note: ''
    };
    setFormData(prev => ({ ...prev, items: [...prev.items, newItem] }));
  };

  const removeItem = (id: string) => {
    setFormData(prev => {
      const newItems = prev.items.filter(item => item.id !== id).map((item, idx) => ({ ...item, stt: idx + 1 }));
      const newTotal = newItems.reduce((sum, item) => sum + (item.total || 0), 0);
      return { ...prev, items: newItems, totalAmount: newTotal };
    });
  };

  const handleExport = () => {
    exportToDocx(formData);
  };

  return (
    <div className="min-h-screen p-4 md:p-8 bg-slate-100">
      <div className="max-w-5xl mx-auto space-y-6">
        <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-5 rounded-xl shadow-sm border border-slate-200">
          <div>
            <h1 className="text-xl font-bold text-slate-900 flex items-center gap-2">
              <FileText className="text-blue-600" />
              BTI AI Extractor
            </h1>
            <p className="text-sm text-slate-500">Trình duyệt & Trích xuất Tờ trình</p>
          </div>

          <div className="flex items-center gap-2">
            <label className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg cursor-pointer hover:bg-blue-700 transition-colors font-medium text-sm">
              <Upload size={16} />
              Tải hồ sơ PDF
              <input type="file" accept=".pdf" className="hidden" onChange={handleFileUpload} />
            </label>
            <button 
              onClick={handleExport}
              className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors font-medium text-sm"
            >
              <Download size={16} />
              Tải file Word
            </button>
          </div>
        </header>

        {error && (
          <div className="flex items-center gap-3 p-4 bg-red-50 text-red-700 border border-red-200 rounded-lg text-sm">
            <AlertCircle size={18} />
            <p>{error}</p>
          </div>
        )}

        {isProcessing && (
          <div className="fixed inset-0 bg-white/80 backdrop-blur-sm z-50 flex flex-col items-center justify-center">
            <Loader2 className="w-10 h-10 text-blue-600 animate-spin mb-4" />
            <p className="text-base font-medium text-slate-900">AI đang xử lý thông tin biểu mẫu...</p>
          </div>
        )}

        <main className="bg-white rounded-lg shadow-xl border border-slate-300 overflow-hidden mx-auto">
          <div className="document-font p-12 md:p-16 space-y-8 w-full bg-white text-black min-h-[1123px]">
            <div className="grid grid-cols-[1.2fr_3fr_1fr] border border-black">
              <div className="border-r border-black p-4 flex items-center justify-center">
