              new TableRow({
                children: [
                  new TableCell({ columnSpan: 5, children: [new Paragraph({ text: "Tổng cộng (đã bao gồm thuế GTGT)", bold: true, alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ text: formData.totalAmount.toLocaleString('vi-VN'), bold: true, alignment: AlignmentType.RIGHT })] }),
                  new TableCell({ children: [new Paragraph({ text: "" })] }),
