          new Paragraph({ text: "..........................................................................................................................................." }),

          new Paragraph({ spacing: { before: 400 } }),
          new Paragraph({ text: "Trân trọng!", alignment: AlignmentType.LEFT }),

          // Signatures Section - Using TextRun with bold: true for guaranteed appearance
          new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
              top: { style: BorderStyle.NONE },
              bottom: { style: BorderStyle.NONE },
              left: { style: BorderStyle.NONE },
              right: { style: BorderStyle.NONE },
              insideHorizontal: { style: BorderStyle.NONE },
              insideVertical: { style: BorderStyle.NONE },
            },
            rows: [
              new TableRow({
                children: [
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Phòng Kế toán", bold: true })], alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Phòng Kỹ thuật", bold: true })], alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Người lập", bold: true })], alignment: AlignmentType.CENTER })] }),
                ],
              }),
              new TableRow({ 
                height: { value: 1200, rule: HeightRule.ATLEAST }, 
                children: [
                  new TableCell({ children: [] }), 
                  new TableCell({ children: [] }), 
                  new TableCell({ children: [] })
                ] 
              }),
              new TableRow({
                children: [
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Phòng Kinh doanh", bold: true })], alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Giám đốc", bold: true })], alignment: AlignmentType.CENTER })] }),
                  new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: "Duyệt HĐTV", bold: true })], alignment: AlignmentType.CENTER })] }),
                ],
