                {formData.grounds.map((ground, idx) => (
                  <div key={idx} className="flex gap-2 items-start">
                    <span className="font-bold">-</span>
                    <textarea 
                      className="w-full bg-transparent border-none focus:ring-0 p-0 resize-none h-auto min-h-[1.3em]"
                      value={ground}
