  ],
  items: [],
  totalAmount: 0
};

const ALLOWED_MIME_TYPES = [
  'application/pdf',
  'image/jpeg',
  'image/png',
  'image/jpg'
];

export default function App() {
  const [formData, setFormData] = useState<FormData>(INITIAL_FORM);
