  category: '',
  address: '',
  senderCompany: '',
  senderRepresentative: '',
  senderPosition: '',
  receiverCompany: 'Công ty TNHH MTV Thương Mại Becamex',
  receiverList: [],
  startTime: '',
  startDate: '',
  endTime: '',
  endDate: '',
