              <Upload size={16} />
              Tải hồ sơ PDF / Ảnh
              <input type="file" className="hidden" onChange={handleFileUpload} />
            </label>
            {hasData && (
              <button 
                onClick={() => exportToDocx(bm02Data)}
                className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg border border-slate-200"
                title="Tải file Word (BM02)"
              >
                <Download size={20} />
              </button>
            )}
          </div>
        </div>

        {/* Tab Switcher */}
        <div className="max-w-6xl mx-auto px-4 flex gap-8">
          <button 
            onClick={() => setActiveTab('BM02')}
            className={`py-3 text-sm font-bold border-b-2 transition-all ${activeTab === 'BM02' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
          >
            ĐN CCVT (BM02)
          </button>
          <button 
            onClick={() => setActiveTab('BBNT')}
            className={`py-3 text-sm font-bold border-b-2 transition-all ${activeTab === 'BBNT' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
          >
            BBNT (BM03.2)
          </button>
        </div>
      </header>

      {/* Vùng nội dung chính */}
      <main className="flex-1 p-6 md:p-10 overflow-y-auto">
        {isProcessing && (
          <div className="fixed inset-0 bg-white/60 backdrop-blur-md z-50 flex flex-col items-center justify-center">
            <Loader2 className="w-12 h-12 text-blue-600 animate-spin mb-4" />
            <p className="font-bold text-slate-800 animate-pulse tracking-wide">AI ĐANG PHÂN TÍCH TÀI LIỆU...</p>
          </div>
        )}

        {error && (
          <div className="max-w-4xl mx-auto mb-6 flex items-center gap-3 p-4 bg-red-50 text-red-700 border border-red-200 rounded-lg">
            <AlertCircle size={20} />
            <p className="font-medium">{error}</p>
          </div>
        )}

        {activeTab === 'BM02' ? (
          <div className="bg-white shadow-2xl rounded-sm border border-slate-300 mx-auto max-w-[800px] document-font p-12 md:p-16 space-y-8 min-h-[1100px] text-black relative">
            {/* Form BM02 Header */}
            <div className="grid grid-cols-[1.2fr_3fr_1fr] border border-black">
              <div className="border-r border-black p-4 flex items-center justify-center">
                <div className="bti-logo-container">
                  <div className="bti-box"><span className="bti-letter">B</span></div>
                  <div className="bti-box"><span className="bti-letter">T</span></div>
                  <div className="bti-box"><span className="bti-letter">I</span></div>
