            </div>

            <p>
              Công ty <span className="font-bold">{bm02Data.proposingCompany || "..."}</span> kính trình Công ty BTI xét duyệt cung cấp vật tư để thi công cho công trình của hợp đồng nêu trên, chi tiết như sau:
            </p>

            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <h3 className="font-bold border-b-2 border-black inline-block uppercase underline">1/ Mua vật tư, thiết bị :</h3>
                <button onClick={addBM02Item} className="p-1 text-blue-600 hover:bg-blue-50 rounded-full border border-blue-200 print:hidden"><Plus size={16} /></button>
              </div>
              <table className="w-full border-collapse border border-black text-sm">
                <thead>
                  <tr className="font-bold text-center bg-slate-50">
                    <td className="border border-black p-1 w-10">Stt</td>
                    <td className="border border-black p-1">Vật tư/Thiết bị</td>
                    <td className="border border-black p-1 w-14">Đvt</td>
                    <td className="border border-black p-1 w-12">SL</td>
                    <td className="border border-black p-1 w-24">Đơn giá</td>
                    <td className="border border-black p-1 w-24">Thành tiền</td>
                    <td className="border border-black p-1 w-24">Ghi chú</td>
                  </tr>
                </thead>
                <tbody>
                  {bm02Data.items.map((it, idx) => (
                    <tr key={it.id}>
                      <td className="border border-black p-1 text-center font-bold">{idx + 1}</td>
                      <td className="border border-black p-1">
                          <input className="w-full bg-transparent border-none text-red-600 font-medium focus:ring-0 p-0" value={it.name} onChange={(e) => updateBM02Item(it.id, 'name', e.target.value)} />
                      </td>
                      <td className="border border-black p-1">
                          <input className="w-full bg-transparent border-none text-center text-red-600 focus:ring-0 p-0" value={it.unit} onChange={(e) => updateBM02Item(it.id, 'unit', e.target.value)} />
                      </td>
                      <td className="border border-black p-1 text-center">
                          <input className="w-full bg-transparent border-none text-center focus:ring-0 p-0" type="number" value={it.quantity} onChange={(e) => updateBM02Item(it.id, 'quantity', parseFloat(e.target.value) || 0)} />
                      </td>
                      <td className="border border-black p-1 text-right">
                          <input className="w-full bg-transparent border-none text-right focus:ring-0 p-0" type="number" value={it.unitPrice} onChange={(e) => updateBM02Item(it.id, 'unitPrice', parseFloat(e.target.value) || 0)} />
                      </td>
                      <td className="border border-black p-1 text-right font-bold">{it.total.toLocaleString('vi-VN')}</td>
                      <td className="border border-black p-1">
                          <input className="w-full bg-transparent border-none focus:ring-0 p-0" value={it.note} onChange={(e) => updateBM02Item(it.id, 'note', e.target.value)} />
                      </td>
                    </tr>
                  ))}
                  <tr className="font-bold bg-slate-50">
                    <td colSpan={5} className="border border-black p-1 text-center uppercase">Tổng cộng (đã bao gồm thuế GTGT)</td>
                    <td className="border border-black p-1 text-right">{bm02Data.totalAmount.toLocaleString('vi-VN')}</td>
                    <td className="border border-black p-1"></td>
                  </tr>
                </tbody>
              </table>
            </div>

            {/* Mục 2/ Xác nhận của bộ phận QLVT */}
            <div className="space-y-2 mt-8">
              <h3 className="font-bold border-b-2 border-black inline-block uppercase underline">2/ Xác nhận của bộ phận QLVT (nếu có):</h3>
              <p className="italic text-sm">(Khối lượng còn trong kho được ghi tại cột ghi chú ở bảng trên)</p>
              <div className="border-b border-black border-dotted w-full h-8"></div>
              <div className="border-b border-black border-dotted w-full h-8"></div>
              <p className="mt-4">Trân trọng!</p>
            </div>

