    const file = event.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    setError(null);
    setHasData(false);

    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const mimeType = file.type;
        const base64 = (reader.result as string).split(',')[1];
        const result = await extractDataFromFile(base64, mimeType);

        setBm02Data({ ...result.bm02, originalFileName: file.name.split('.')[0] });
        setBbntData({ ...result.bbnt, originalFileName: file.name.split('.')[0] });

        setIsProcessing(false);
        setHasData(true);
      };
      reader.readAsDataURL(file);
    } catch (err: any) {
      setError(err.message || "Đã có lỗi xảy ra.");
      setIsProcessing(false);
