            <div className="text-right italic text-red-600 flex justify-end gap-1 items-center">
                <input className="bg-transparent border-none text-right focus:ring-0 p-0 italic w-44" value={bm02Data.location} onChange={(e) => setBm02Data({...bm02Data, location: e.target.value})} />,
                <input className="bg-transparent border-none text-left focus:ring-0 p-0 italic w-80" value={bm02Data.date} onChange={(e) => setBm02Data({...bm02Data, date: e.target.value})} />
            </div>

            <div className="space-y-4">
              <div className="flex gap-4">
                <span className="font-bold min-w-[80px]">Kính gửi:</span>
                <div className="flex-1 space-y-1 font-bold">
                  {bm02Data.recipients.map((r, i) => <div key={i} className="flex gap-2"><span>-</span><input className="bg-transparent border-none focus:ring-0 p-0 w-full" value={r} onChange={(e) => {
